const raw = $('Retell Tool Call').first().json.body || $('Retell Tool Call').first().json;
let body;
if (raw.arguments !== undefined) {
  body = typeof raw.arguments === 'string' ? JSON.parse(raw.arguments) : raw.arguments;
} else {
  body = raw;
}

const telefono = String(body.telefono || '').trim();
const fecha = String(body.fecha || '').trim();
const hora = String(body.hora || '').trim();

// Formatear fecha para mensaje
const fechaObj = new Date(fecha + 'T00:00:00');
const diasSemana = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const meses = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
const diaSemana = diasSemana[fechaObj.getUTCDay()];
const diaMes = fechaObj.getUTCDate();
const mes = meses[fechaObj.getUTCMonth()];

// Calcular ventana de búsqueda (día completo + margen)
const fechaInicioDia = new Date(fecha + 'T00:00:00').toISOString();
const fechaFinDia = new Date(fecha + 'T23:59:59').toISOString();

return [{ json: { 
  telefono, 
  fecha, 
  hora, 
  diaSemana, 
  diaMes, 
  mes,
  fechaInicioDia,
  fechaFinDia
}}];

const eventos = $('Google Calendar - Buscar Evento').all();
const datos = $('Parsear Argumentos').first().json;

// Buscar evento que coincida con la hora aproximada
const eventoEncontrado = eventos.find(e => {
  const start = e.json.start?.dateTime || e.json.start?.date;
  if (!start) return false;
  const horaEvento = start.split('T')[1]?.substring(0, 5);
  return horaEvento === datos.hora;
});

if (!eventoEncontrado) {
  return [{
    json: {
      cancelado: false,
      error: 'No se encontró la cita en Google Calendar',
      mensaje: 'No encontré esa cita en el calendario. ¿Estás seguro de la fecha y hora?'
    }
  }];
}

return [{ json: {
  ...datos,
  evento_id: eventoEncontrado.json.id,
  evento_summary: eventoEncontrado.json.summary
}}];

const deleteResult = $('Google Calendar - Eliminar').first().json;
const datos = $('Filtrar Evento por Hora').first().json;

if (deleteResult === undefined || deleteResult === null || deleteResult.success !== false) {
  const mensaje = `Tu cita del ${datos.diaSemana} ${datos.diaMes} de ${datos.mes} a las ${datos.hora} ha quedado cancelada. ¡Hasta la próxima!`;

  return [{
    json: {
      cancelado: true,
      resumen: `Cita de ${datos.evento_summary} cancelada`,
      mensaje: mensaje,
      google_calendar_event_id: datos.evento_id
    }
  }];
} else {
  return [{
    json: {
      cancelado: false,
      error: 'No se pudo eliminar el evento',
      mensaje: 'Hubo un problema al cancelar la cita. Por favor, llama al salón.'
    }
  }];
}
